def a(n, memo):
    if n in memo:
        return memo[n]
    if n == 1 or n == 2:
        return 1

    # Recurrence: a_n = a_{a_{n-1}} + a_{n - a_{n-1}}

    a_n_minus_1 = a(n - 1, memo)

    term1 = a(a_n_minus_1, memo)
    term2 = a(n - a_n_minus_1, memo)

    result = term1 + term2
    memo[n] = result
    return result

