def calculate_a_n(N):
    """
    Calculates the sequence terms a_1 through a_N based on the recurrence relation.
    a_n = 1 for n=1, 2
    a_n = a_{a_{n-1}} + a_{n - a_{n-1}} otherwise
    """
    a = {}
    a[1] = 1
    a[2] = 1

    for n in range(3, N + 1):
        # a_{n-1} must be known, which it is since n-1 < n
        # a_{n - a_{n-1}} requires a_{n-1} which is known

        # We need a_{n-1}.
        try:
            a_n_minus_1 = a[n-1]
        except KeyError:
            # Should not happen if N is reached sequentially
            print(f"Error: a_{n-1} not yet calculated.")
            return {}

        # Check if a_{a_{n-1}} is defined. Since a_n is positive integer, a_{n-1} >= 1.
        # Since n-1 >= 2, a_{n-1} >= 1. We assume a_n is monotonically non-decreasing and grows, 
        # so a_{n-1} should be <= n-1 eventually, making a_{n-1} within the calculated range.
        # However, for safety, we must ensure the index a_{n-1} is within the currently calculated bounds (1 to n-1).

        idx1 = a_n_minus_1
        if idx1 not in a:
            # This indicates a potential issue if a_n grows faster than n
            # Given the conjecture a_n ~ 0.57n, this should not happen for N=4096.
            print(f"Error: Index {idx1} required for a_n calculation is out of bounds.")
            return {}

        try:
            term1 = a[idx1]
        except KeyError:
            print(f"Critical Error: a_{idx1} not found in dictionary.")
            return {}

        # Check if a_{n - a_{n-1}} is defined.
        idx2 = n - a_n_minus_1
        if idx2 <= 0:
            print(f"Error: Index {idx2} is non-positive.")
            return {}
        if idx2 not in a:
            # This indicates a potential issue if a_n grows too fast relative to n
            print(f"Error: Index {idx2} required for a_n calculation is out of bounds.")
            return {}

        try:
            term2 = a[idx2]
        except KeyError:
            print(f"Critical Error: a_{idx2} not found in dictionary.")
            return {}


        a[n] = term1 + term2

    return a

